from collections import Counter

class Solution:
    def countCharacters(self, words: list[str], chars: str) -> int:
        base = Counter(chars)
        total = 0
        for w in words:
            cw = Counter(w)
            if all(cw[c] <= base[c] for c in cw):
                total += len(w)
        return total

class Solution {
public:
    int countCharacters(vector<string>& words, string chars) {
        vector<int> base(26, 0);
        for (char c : chars) base[c - 'a']++;

        int total = 0;
        for (const string& w : words) {
            vector<int> curr(26, 0);
            bool ok = true;
            for (char c : w) {
                if (++curr[c - 'a'] > base[c - 'a']) {
                    ok = false;
                    break;
                }
            }
            if (ok) total += w.size();
        }
        return total;
    }
};

class Solution {
    public int countCharacters(String[] words, String chars) {
        int[] base = new int[26];
        for (char c : chars.toCharArray()) base[c - 'a']++;

        int total = 0;
        for (String w : words) {
            int[] curr = new int[26];
            boolean ok = true;
            for (char c : w.toCharArray()) {
                if (++curr[c - 'a'] > base[c - 'a']) {
                    ok = false;
                    break;
                }
            }
            if (ok) total += w.length();
        }
        return total;
    }
}

var countCharacters = function(words, chars) {
    const base = new Array(26).fill(0);
    const code = (c) => c.charCodeAt(0) - 97;
    for (const c of chars) base[code(c)]++;

    let total = 0;
    for (const w of words) {
        const curr = new Array(26).fill(0);
        let ok = true;
        for (const c of w) {
            const idx = code(c);
            if (++curr[idx] > base[idx]) {
                ok = false;
                break;
            }
        }
        if (ok) total += w.length;
    }
    return total;
};
